import csv
import sqlite3

# Get Riverside districts
rid=[]
with open('csv/frpm.csv') as f:
    r=list(csv.DictReader(f))
    for row in r:
        if 'Riverside' in row.get('District Name',''):
            rid.append(row)

# Map CDSCode to district info
cds_to_info={row['CDSCode']: row for row in rid}

# Connect to DB and get SAT scores
conn=sqlite3.connect('db/satscores.db')
cur=conn.cursor()
cur.execute('SELECT cds, sname, dname, AvgScrMath FROM satscores')
sat_rows=cur.fetchall()
conn.close()

# Group by district
dist_scores={}
dist_schools={}
for cds, sname, dname, asm in sat_rows:
    if cds in cds_to_info:
        if dname not in dist_scores:
            dist_scores[dname]=[]
            dist_schools[dname]={}
        if asm is not None:
            dist_scores[dname].append(asm)
        if sname:
            dist_schools[dname][sname]=cds_to_info[cds]

print('Districts with SAT scores:')
for d, scores in dist_scores.items():
    avg=sum(scores)/len(scores) if scores else 0
    if avg > 400:
        print(f'{d}: avg={avg:.1f}, schools={len(scores)}')
        for sn in dist_schools[d]:
            fi=dist_schools[d][sn]
            print(f'  {sn}: {fi.get("Charter Funding Type","")} / {fi.get("District Type","")}')

